    border_colors = {grid[0][c] for c in range(w)} | {grid[h-1][c] for c in range(w)}
    border_colors |= {grid[r][0] for r in range(h)} | {grid[r][w-1] for r in range(h)}
    marker_colors = {v for row in grid for v in row if v != background and v not in border_colors}
